mapper.select:
SELECT DISTINCT a.customer
FROM fx_pricelist a
WHERE a.distributor_level = #{level}
  AND a.brand_id = #{brand}
  AND (a.is_normal = '0' or a.is_normal is null)
  AND NOT EXISTS (SELECT 1
                  FROM fx_pricelist b
                  WHERE b.sku_id = #{skuId}
                    AND b.customer = a.customer)

mapper.update:
UPDATE fx_pricelist
SET saleprice   = #{salePrice},
    update_time = NOW()
WHERE distributor_level = #{level}
  AND sku_id = #{skuId}
  AND brand_id = #{brand}
  AND (is_normal = '0' or is_normal is null)
